const badge=(label,cls='')=>`<span class="pill ${cls||(/révis|visite|manquant|attente|éché|Bloc|À /i.test(label)?'amber':/Prépa|Nouveau|Démo|validation/i.test(label)?'purple':/Brouillon|Non|Inactif/i.test(label)?'gray':'')}">${esc(label)}</span>`;
