function head(title,sub,buttons=''){return `<div class="pagehead"><div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${buttons?`<div class="actions">${buttons}</div>`:''}</div>`}
function metric(label,value,unit,foot,ic){return `<div class="metric"><div class="metric-top">${label}${icon(ic,17)}</div><div class="metric-value">${value}<small>${unit}</small></div><div class="metric-foot">${foot}</div></div>`}
function tabs(list){return `<div class="tabs" role="group" aria-label="Filtrer">${list.map(x=>`<button data-filter="${x}" class="${filter===x?'active':''}">${x}</button>`).join('')}</div>`}
