function radarArt(){return `<svg class="radar-art" viewBox="0 0 400 290" fill="none" aria-hidden="true"><g transform="translate(240 140)"><circle r="122" stroke="#ddd3ea"/><circle r="90" stroke="#ddd3ea"/><circle r="58" stroke="#ddd3ea"/><circle r="26" stroke="#ddd3ea"/><path d="M-130 0h260M0-130v260" stroke="#e2daec"/><path d="M0 0 102-67A122 122 0 0 1 122 0Z" fill="#e0d5ee" opacity=".7"/><path d="M0 0 102-67" stroke="#bb9ed0" stroke-width="1.5"/><circle cx="-43" cy="-39" r="6" fill="#baa2d0" stroke="#efebf8" stroke-width="4"/><circle cx="70" cy="24" r="7" fill="#b5c9a7" stroke="#efebf8" stroke-width="4"/><circle cx="12" cy="72" r="5" fill="#c2b1d2"/><circle r="4" fill="#b197c9"/></g><rect x="138" y="71" width="106" height="35" rx="7" fill="#fff" stroke="#e5daef"/><circle cx="154" cy="88" r="4" fill="#b0c8a2"/><text x="165" y="91" fill="#a08eb0" font-size="10" font-family="sans-serif">Nouveau match</text><rect x="236" y="177" width="106" height="43" rx="7" fill="#fff" stroke="#e5daef"/><text x="251" y="194" fill="#a08eb0" font-size="9" font-family="sans-serif">Montérégie</text><text x="251" y="208" fill="#b8a9c3" font-size="9" font-family="sans-serif">Dans votre territoire</text></svg>`}
function card(t){return `<article class="tender-card"><div class="card-head"><span class="buyer-mark ${t.color}">${icon('building',20)}</span><div class="buyer-label"><strong>${t.buyer}</strong>${t.source}</div><button class="icon-btn bookmark ${state.saved.includes(t.id)?'saved':''}" data-action="save:${t.id}" aria-label="${state.saved.includes(t.id)?'Retirer des favoris':'Enregistrer'} ${t.short}" aria-pressed="${state.saved.includes(t.id)}">${icon('bookmark',17)}</button></div><h2>${t.title}</h2><div class="tender-meta"><span>${icon('pin',13)}${t.region} · ${t.distance} km</span><span>${icon('wallet',13)}${cad(t.value)} / ${t.term}</span><span>${icon('clock',13)}${t.days} jours</span></div>${state.declined[t.id]?`<div class="notice" style="margin:10px 0">${esc(state.declined[t.id].reason)} · Décision conservée</div>`:''}<div class="tags"><span class="tag">Territoire compatible</span><span class="tag purple">Équipement adapté</span>${t.id==='TS-2026-087'?'<span class="tag peach">Visite obligatoire</span>':'<span class="tag">Références disponibles</span>'}</div><div class="card-footer"><span class="match">${icon('target',14)}${t.match}% de pertinence <span style="color:#bbb8c3;font-size:9px">· fit démo</span></span>${btn('Examiner le dossier','tender:'+t.id,'small','arrow')}</div></article>`}
function bidMini(t){return `<div class="bid-mini"><div class="bid-mini-top"><h3>${t.short}</h3>${badge(stage(t))}</div><p>${t.trade} · Clôture ${t.close}</p><div class="progress"><i style="width:${completion(t.id)}%"></i></div><button data-action="tender:${t.id}">Continuer le dossier ${icon('arrow',13)}</button></div>`}
const views={
radar(){const list=tenders.filter(t=>!state.pursuing.includes(t.id)&&matchesCriteria(t)&&(filter==='Écartés'?Boolean(state.declined[t.id]):!state.declined[t.id])&&(!query||JSON.stringify(t).toLowerCase().includes(query.toLowerCase()))&&(filter==='Tout'||filter==='Écartés'||filter==='Enregistrés'&&state.saved.includes(t.id)||t.trade===filter));return head('Bonjour, Alexandre.','Vos prochains contrats commencent ici. · Vendredi 23 octobre 2026',btn('Mes critères','criteria','','filter')+btn('Voir mes soumissions','page:bids','primary','arrow'))+`<div class="metrics">${metric('Nouvelles opportunités',radarCount(),'','<span class="positive">Critères appliqués</span> · '+state.radius+' km','radar')}${metric('Soumissions en cours',state.pursuing.length,'',state.approved.filter(isApproved).length+' prêtes à exporter','book')}${metric('Valeur en préparation',(tenders.filter(t=>state.pursuing.includes(t.id)&&!state.receipts[t.id]).reduce((sum,t)=>sum+t.value,0)/1000000).toLocaleString('fr-CA',{maximumFractionDigits:2}),'M$','Montants estimés · avant taxes','chart')}${metric('Prochaine clôture','27','oct.','Transport de neige · Beloeil','calendar')}</div><section class="hero"><div class="hero-text"><div class="eyebrow">LE BON CONTRAT, AU BON MOMENT</div><h2>Votre radar a fait le premier tri.</h2><p>Des occasions qui correspondent à votre métier, votre territoire et votre capacité. À vous de choisir la suite.</p><div class="hero-steps"><span>${icon('check',12)}Territoire ciblé</span><span>${icon('check',12)}Critères expliqués</span><span>${icon('file',12)}Sources reliées</span></div></div>${radarArt()}</section><div class="grid"><section><div class="section-head"><div><h2>À explorer aujourd’hui</h2><p>La pertinence ne remplace pas la vérification des exigences.</p></div>${badge(list.length+' dossiers','gray')}</div><div class="toolbar">${tabs(['Tout','Déneigement','Enregistrés','Écartés'])}</div><div class="stack">${list.map(card).join('')||'<div class="panel empty">Aucun dossier dans cette vue.</div>'}</div></section><div class="stack" style="align-content:start"><section class="panel"><div class="panel-head"><h2>Gardez le cap</h2>${icon('book',17)}</div><div class="panel-body">${state.pursuing.map(id=>tenders.find(t=>t.id===id)).slice(0,3).map(bidMini).join('')}</div></section><section class="panel"><div class="panel-head"><h2>Ce qui a changé</h2></div><div class="panel-body"><div class="activity"><span class="activity-icon">${icon('file',15)}</span><div><p><strong>Sainte-Julie</strong><br>Un addenda modifie les quantités.</p><small>Aujourd’hui · 08 h 42</small><button class="btn link" style="font-size:10px" data-action="addendum:TS-2026-081">Voir l’impact →</button></div></div><div class="activity"><span class="activity-icon">${icon('shield',15)}</span><div><p>Assurance responsabilité<br>Attestation à vérifier avant dépôt.</p><small>Aujourd’hui · 07 h 30</small></div></div><div class="activity"><span class="activity-icon">${icon('radar',15)}</span><div><p>${radarCount()} dossiers correspondent aux critères.</p><small>Instantané démo · 06 h 00</small></div></div></div></section><p class="note">Avis, entreprises, prix et documents sont fictifs. Aucune connexion aux portails publics.</p></div></div>`},
bids(){const list=tenders.filter(t=>state.pursuing.includes(t.id));return head('Une place pour chaque dossier.','De la première lecture au reçu de dépôt, chaque étape reste visible.',btn('Exporter le suivi','export-tracker','','download')+btn('Explorer le radar','page:radar','primary','plus'))+`<div class="toolbar">${tabs(['Tout','En préparation','Prêtes','Déposées'])}${search('Rechercher un dossier')}</div><div class="kanban">${[['À réviser',['À réviser']],['Préparation',['Préparation']],['Validation',['Validation','Prête']],['Déposées',['Déposée']]].map(([name,statuses])=>{let ts=list.filter(t=>statuses.includes(stage(t))&&JSON.stringify(t).toLowerCase().includes(query.toLowerCase())&&(filter==='Tout'||filter==='En préparation'&&['À réviser','Préparation','Validation'].includes(stage(t))||filter==='Prêtes'&&stage(t)==='Prête'||filter==='Déposées'&&stage(t)==='Déposée'));return `<section class="kanban-col"><div class="kanban-head">${name}<span>${ts.length}</span></div>${ts.map(t=>`<article class="kanban-card">${badge(t.days+' jours avant clôture',t.days<7?'amber':'purple')}<h3>${t.short}<br>${t.title.split(' — ')[0]}</h3><p>${cad(t.value)} · ${t.term}</p><div class="progress"><i style="width:${completion(t.id)}%"></i></div><footer><span class="avatar round" style="width:26px;height:26px;font-size:9px">${t.owner}</span><span>${t.close}</span><button aria-label="Ouvrir ${t.short}" data-action="tender:${t.id}">${icon('arrow',16)}</button></footer></article>`).join('')||'<div class="empty" style="padding:40px 5px;font-size:10px">Les dossiers de cette étape<br>apparaîtront ici.</div>'}</section>`}).join('')}</div><div class="notice purple">${icon('shield',18)}<span>Exporter un dossier ne signifie pas le déposer. Le statut « Déposée » demande un reçu saisi après transmission par le canal officiel.</span></div>`},
workbench(){const t=tender();return `<div class="workhead"><button class="icon-btn back" aria-label="Retour au radar" data-page="radar">${icon('arrow',19)}</button><div><div class="eyebrow">${t.source} · DOSSIER FICTIF</div><h1>${t.title}</h1><div class="work-meta"><span>${t.buyer}</span><span>${icon('clock',11)} ${t.close} · 10 h</span>${badge(stage(t))}<span>Version 2</span></div></div><div class="actions">${btn(state.saved.includes(t.id)?'Enregistré':'Enregistrer','save:'+t.id,'','bookmark')}${!state.pursuing.includes(t.id)?btn('Poursuivre ce dossier','pursue:'+t.id,'primary','plus'):btn('Voir la validation','tab:Validation','primary','check')}</div></div><div class="work-tabs" role="tablist" aria-label="Dossier">${['Synthèse','Exigences','Chiffrage','Documents','Validation'].map(s=>`<button role="tab" aria-selected="${s===workTab}" class="${s===workTab?'active':''}" data-action="tab:${s}">${s}${s==='Exigences'?` <span style="font-size:9px;margin-left:4px">${requirements.filter(r=>checked(t.id,r[0])).length}/8</span>`:''}</button>`).join('')}</div>${workViews[workTab](t)}`},
intelligence(){return head('Un prix éclairé par les faits.','Des contrats comparables pour situer votre estimation. Pas une promesse de gagner.',btn('Exporter les comparables','export-prices','','download'))+`<div class="toolbar">${tabs(['Déneigement','Transport','Entretien'])}<span class="note" style="margin-left:auto">Échantillon fictif · 2023–2025 · Avant taxes</span></div><div class="grid"><section class="panel"><div class="panel-head"><div><h2>${filter==='Transport'?'Transport de neige':filter==='Entretien'?'Entretien municipal':'Déneigement municipal'}</h2><p>Trois saisons · Montérégie · Prix d’ouverture publiés (simulation)</p></div></div><div class="panel-body">${[['Nord-Est Services',1140000],['Groupe des Rives',1185000],['Excavation Mont-Val',1290000],['Services Hivernis',1325000]].map((x,i)=>`<div class="price-bar"><span>${x[0]}</span><div class="track"><i style="width:${x[1]/1500000*100}%;background:${i===0?'#a28aba':'#d7c6e3'}"></i></div><b>${cad(filter==='Transport'?x[1]*.42:filter==='Entretien'?x[1]*.3:x[1])}</b></div>`).join('')}<div class="notice purple">${icon('file',18)}<span>4 prix d’ouverture comparables dans cet exemple. Les écarts de quantité, de durée et d’indexation doivent être vérifiés.</span></div></div></section><section class="panel"><div class="panel-head"><h2>Lecture de l’échantillon</h2></div><div class="panel-body"><div class="cost-row"><span>Prix le plus bas</span><strong>${cad(filter==='Transport'?478800:filter==='Entretien'?342000:1140000)}</strong></div><div class="cost-row"><span>Écart entre 1er et 2e</span><strong>3,9%</strong></div><div class="cost-row"><span>Résultats connus</span><strong>4 sur 4</strong></div><div class="cost-row"><span>Période observée</span><strong>2023–2025</strong></div><p class="note" style="margin-top:22px">Les prix historiques n’indiquent ni le coût réel d’un concurrent ni le prix d’un futur gagnant.</p></div></section></div><section class="panel" style="margin-top:24px"><div class="panel-head"><h2>Contrats comparables</h2>${badge('Provenance visible','purple')}</div><div class="table-wrap"><table><thead><tr><th>Donneur d’ordre</th><th>Objet / durée</th><th>Année</th><th>Montant retenu</th><th>Couverture</th><th></th></tr></thead><tbody>${[['Saint-Bruno','Secteur Est · 3 saisons','2023',1140000,'4 prix'],['Boucherville','Stationnements · 2 saisons','2024',398000,'2 prix'],['Sainte-Julie','Secteur Centre · 3 saisons','2023',862000,'3 prix']].map((r,i)=>`<tr><td><strong>${r[0]}</strong></td><td>${filter==='Transport'?'Transport de neige · '+(r[1].includes('2 saisons')?'2':'3')+' saisons':filter==='Entretien'?'Entretien · '+(r[1].includes('2 saisons')?'2':'3')+' saisons':r[1]}</td><td>${r[2]}</td><td>${cad(r[3]*historyFactor())}</td><td>${badge(r[4])}</td><td><button class="source-link" data-action="historical:${i}">Voir les détails</button></td></tr>`).join('')}</tbody></table></div></section>`},
vault(){const docs=[['Assurance responsabilité civile','Assurances','5 M$ · 31 mars 2027','À vérifier','insurance'],['Attestation fiscale','Conformité','Vérifier selon le devis','À vérifier','tax'],['Profil de l’entreprise','Entreprise','Version 3 · 21 octobre','Vérifié (démo)','identity'],['Autorisation AMP / statut REA','Conformité','Statut et obligations à vérifier','Revue requise','amp'],['Projet de référence · Saint-Bruno','Références','Déneigement · 2023–2025','Vérifié (démo)','references'],['Parc de 12 équipements','Équipements','8 chasse-neige · 4 chargeurs','Vérifié (démo)','equipment'],...state.documents.map((d,i)=>[d.name,d.type,'Ajout local · métadonnées','À vérifier','local-'+i])].filter(d=>(filter==='Tout'||d[1]===filter)&&d.join(' ').toLowerCase().includes(query.toLowerCase()));return head('Votre mémoire d’entreprise.','Des preuves réutilisables. Une source claire pour chaque formulaire.',btn('Profil entreprise','company-profile','','building')+btn('Ajouter un document','add-document','primary','plus'))+`<div class="metrics">${metric('Documents',6+state.documents.length,'','Classés dans votre espace démo','file')}${metric('Références projet',3,'','Toutes réutilisables après revue','book')}${metric('Vérifications à faire',3,'','Assurance · fiscalité · autorisation','shield')}${metric('Équipements',12,'','8 chasse-neige · 4 chargeurs','truck')}</div><div class="toolbar">${tabs(['Tout','Conformité','Assurances','Références','Équipements'])}${search('Rechercher une preuve')}</div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Document / preuve</th><th>Catégorie</th><th>Validité / contexte</th><th>État</th><th></th></tr></thead><tbody>${docs.map(d=>`<tr><td><span class="file-icon">${icon('file',17)}</span><strong>${esc(d[0])}</strong></td><td>${esc(d[1])}</td><td>${esc(d[2])}</td><td>${badge(d[3])}</td><td><button class="icon-btn" aria-label="Voir ${esc(d[0])}" data-action="vault-doc:${d[4]}">${icon('arrow',15)}</button></td></tr>`).join('')}</tbody></table></div>${!docs.length?'<div class="empty">Aucun document ne correspond à votre recherche.</div>':''}</section><div class="notice purple">${icon('shield',18)}<span>L’autorisation AMP est présentée comme une vérification de statut et d’obligations. Aucune date d’expiration universelle n’est inventée.</span></div>`},
calendar(){let offset=calendarNext?26:19;return head('Les bonnes dates, au bon endroit.','Visites, revues et clôtures. Heure de Montréal, selon le dossier.',btn(calendarNext?'← 19–23 octobre':'26–30 octobre →','calendar-week','','calendar'))+`<div class="calendar"><div class="panel-head"><h2>${calendarNext?'26 au 30':'19 au 23'} octobre 2026</h2>${badge('Semaine','purple')}</div><div class="week-grid">${['Lundi','Mardi','Mercredi','Jeudi','Vendredi'].map((day,i)=>`<div class="day ${!calendarNext&&i===4?'today':''}"><div class="day-head">${day}<strong>${offset+i}</strong></div>${calendarNext?(i===1?`<button class="event amber" data-action="tender:TS-2026-069">10 h · Clôture<strong>Beloeil</strong>Transport de neige</button>`:i===2?`<button class="event" data-action="event:visit">10 h · Visite obligatoire<strong>Saint-Bruno</strong>Point de rencontre à confirmer</button>`:i===3?`<button class="event amber" data-action="tender:TS-2026-076">10 h · Clôture<strong>Varennes</strong>Entretien hivernal</button>`:i===4?`<button class="event amber" data-action="tender:TS-2026-081">10 h · Clôture<strong>Sainte-Julie</strong>Version 2 requise</button>`:`<button class="event" data-action="task:new">9 h · Préparation<strong>Revue d’équipe</strong>Prix et pièces manquantes</button>`):(i===1?`<button class="event" data-action="tender:TS-2026-081">10 h · Visite effectuée<strong>Sainte-Julie</strong>Note terrain disponible</button>`:i===3?`<button class="event" data-action="vault-doc:insurance">14 h · Documents<strong>Assurance responsabilité</strong>Revue de l’attestation</button>`:i===4?`<button class="event" data-action="tender:TS-2026-069">11 h · Revue finale<strong>Beloeil</strong>Signature et pièces</button>`:'')}</div>`).join('')}</div></div><div class="notice purple">${icon('calendar',18)}<span>Calendrier de démonstration. Les dates sont celles des dossiers fictifs; aucune synchronisation externe.</span></div>`},
team(){return head('Une équipe. Un dossier à jour.','Responsabilités claires, décisions traçables et accès limités.',btn('Créer une tâche','task:new','primary','plus'))+`<div class="grid"><section class="panel"><div class="panel-head"><h2>À faire ensemble</h2>${badge((3+state.tasks.length)+' tâches','purple')}</div><div class="panel-body">${[['Vérifier le nouvel addenda','Sainte-Julie · Alexandre Roy','Aujourd’hui','addendum:TS-2026-081'],['Confirmer la visite obligatoire','Saint-Bruno · Marie Lavoie','28 oct.','event:visit'],['Revoir l’attestation d’assurance','Coffre-fort · Claire Dubois','26 oct.','vault-doc:insurance'],...state.tasks.map((t,i)=>[t.title,`${t.owner} · Tâche locale`,t.done?'Terminée':t.date,'task-toggle:'+i])].map(t=>`<div class="requirement"><span class="avatar round">${t[1].includes('Marie')?'ML':t[1].includes('Claire')?'CD':'AR'}</span><div><h3>${esc(t[0])}</h3><p>${esc(t[1])} · ${esc(t[2])}</p></div><button class="icon-btn" style="margin-left:auto" aria-label="Ouvrir ${esc(t[0])}" data-action="${t[3]}">${icon('arrow',15)}</button></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>Votre équipe</h2>${btn('Ajouter','new-member','link','plus')}</div><div class="panel-body">${[['AR',state.person,'Propriétaire · Signataire'],['ML','Marie Lavoie','Estimatrice'],['CD','Claire Dubois','Administration'],...state.team.map(t=>[t.name.split(' ').map(x=>x[0]).join('').slice(0,2),t.name,t.role])].map(p=>`<div class="activity"><span class="avatar round">${esc(p[0])}</span><div><h3 style="font-size:11px">${esc(p[1])}</h3><small style="font-size:10px;color:#ad98bd;margin-top:6px;display:block">${esc(p[2])}</small></div></div>`).join('')}</div></section></div><section class="panel" style="margin-top:23px"><div class="panel-head"><h2>Journal de décisions</h2>${badge('Local · Démo','gray')}</div><div class="panel-body">${(state.activity.length?state.activity:['Addenda 01 détecté · Sainte-Julie · Revue requise','Profil entreprise mis à jour · Version 3','Premiers dossiers ajoutés au radar']).slice(0,8).map(a=>`<div class="activity"><span class="activity-icon">${icon('check',15)}</span><div><p>${esc(a)}</p><small>Instantané local · ${esc(state.person)}</small></div></div>`).join('')}</div></section>`},
settings(){return head('Un radar à votre mesure.','Entreprise, préférences et contrôles de démonstration.')+`<div class="grid"><section class="panel"><div class="panel-head"><h2>Profil et territoire</h2></div><div class="panel-body"><form id="settings-form" class="form"><div class="form-row"><label>Entreprise<input name="company" value="${esc(state.company)}" required maxlength="60"></label><label>Responsable<input name="person" value="${esc(state.person)}" required maxlength="60"></label></div><div class="form-row"><label>Territoire principal<select><option>Montérégie</option></select></label><label>Rayon indicatif (km)<input name="radius" type="number" min="10" max="500" value="${state.radius}" required></label></div><label>Métiers inclus<select><option>Déneigement, transport et entretien</option></select></label><button class="btn primary" type="submit" style="justify-self:start">Enregistrer</button></form><div class="setting"><div><h3>Brief du matin</h3><p>Résumé démo à 7 h 30 · America/Toronto</p></div><button class="toggle" role="switch" aria-label="Brief du matin" aria-checked="${state.digest}" data-action="toggle:digest"></button></div><div class="setting"><div><h3>Alertes prioritaires</h3><p>Préférence SMS mémorisée localement. Aucun SMS envoyé.</p></div><button class="toggle" role="switch" aria-label="Alertes prioritaires" aria-checked="${state.sms}" data-action="toggle:sms"></button></div></div></section><div class="stack"><section class="panel"><div class="panel-head"><h2>Sources et couverture</h2></div><div class="panel-body"><div class="cost-row"><span>SEAO</span>${badge('Simulation','purple')}</div><div class="cost-row"><span>CanadaBuys</span>${badge('Non connecté','gray')}</div><div class="cost-row"><span>SAM.gov</span>${badge('Non connecté','gray')}</div><div class="notice purple">${icon('shield',17)}<span>Toutes les données sont fictives. Les statuts de conformité ne sont pas des vérifications réelles.</span></div></div></section><section class="panel"><div class="panel-head"><h2>Conseil et relève</h2></div><div class="panel-body"><p class="note">Une conversation facultative, avec un partage séparé et explicite. Le coffre-fort reste privé par défaut.</p><div class="setting"><h3>Intérêt pour une introduction</h3><button class="toggle" role="switch" aria-label="Intérêt pour un conseil en relève" aria-checked="${state.referral}" data-action="toggle:referral"></button></div></div></section><section class="panel"><div class="panel-head"><h2>Espace de démonstration</h2></div><div class="panel-body">${btn('Réinitialiser les données','reset','','logout')}</div></section></div></div>`}
};
const sourceCopy={identity:['Annexe A — Identification','3','L’entreprise indique sa dénomination, ses coordonnées et le nom de son représentant autorisé. Les déclarations sont revues par ce représentant.'],insurance:['4.2 — Assurance responsabilité','18','L’adjudicataire doit maintenir une assurance responsabilité civile de cinq millions de dollars (5 000 000 $) pour la durée du contrat.'],visit:['3.4 — Visite des lieux','12','Une visite obligatoire est prévue le 28 octobre 2026 à 10 h. Le soumissionnaire doit faire constater sa présence par le représentant désigné.'],references:['Annexe C — Expérience pertinente','7','Présenter trois projets comparables complétés au cours des cinq dernières années, avec le client, la période et la nature des travaux.'],bond:['5.1 — Garantie de soumission','21','La garantie demandée pour ce dossier fictif est de cinq pour cent (5%) du prix soumis avant taxes. Le formulaire applicable doit être utilisé.'],tax:['Annexe D — Attestation','2','Joindre l’attestation fiscale requise selon la période et les conditions de validité précisées dans les instructions aux soumissionnaires.'],addendum:['Addenda 01 — Bordereau révisé','1','La longueur du réseau à desservir passe de 42,0 km à 46,5 km. Le bordereau version 2 remplace la version 1. Les prix doivent être revus.'],price:['Bordereau — Déclaration finale','4','Les montants sont indiqués avant taxes. Les cases obligatoires sont complétées et la déclaration est revue puis signée par le représentant autorisé.']};
function paper(key){const s=sourceFor(key);return `<aside class="source-view"><div class="source-toolbar"><span>${icon('file',12)} Extrait de démonstration</span><span>Page ${s[1]}</span></div><div class="paper"><div class="paper-label">DOCUMENT FICTIF · VERSION 2</div><h3>${s[0]}</h3><p>Appel d’offres ${activeTender}<br>${tender().buyer}</p><p><mark>${s[2]}</mark></p><div class="paper-lines"></div><p style="font-size:9px;margin-top:30px;color:#b9a5c7">Cet extrait illustre les liens entre exigences et preuves. Il ne provient pas d’un avis public réel.</p></div></aside>`}
function priceValues(t){const factor=t.value/1240000;return state.prices[t.id]||{labor:Math.round(420000*factor),equipment:Math.round(285000*factor),materials:Math.round(110000*factor),overhead:Math.round(95000*factor),contingency:Math.round(40000*factor),margin:15}}
function validPrice(p){return Boolean(p)&&['labor','equipment','materials','overhead','contingency'].every(k=>p[k]!==''&&Number.isFinite(Number(p[k]))&&Number(p[k])>=0&&Number(p[k])<=10000000)&&['labor','equipment','materials','overhead','contingency'].some(k=>Number(p[k])>0)&&p.margin!==''&&Number.isFinite(Number(p.margin))&&Number(p.margin)>=0&&Number(p.margin)<=60}
function calcPrice(p){if(!validPrice(p))return {valid:false,cost:0,price:0,profit:0};const cost=['labor','equipment','materials','overhead','contingency'].reduce((s,k)=>s+Number(p[k]),0);return {valid:true,cost,price:cost/(1-Number(p.margin)/100),profit:cost/(1-Number(p.margin)/100)-cost}}
function invalidate(id){if(state.approvalSnapshots[id]){state.packageHistory||=[];state.packageHistory.push({tender:id,...state.approvalSnapshots[id]});delete state.approvalSnapshots[id]}delete state.exportSnapshots[id];state.approved=state.approved.filter(x=>x!==id);state.exported=state.exported.filter(x=>x!==id);if(state.receipts[id]){state.receiptHistory=state.receiptHistory||[];state.receiptHistory.push({tender:id,...state.receipts[id]});delete state.receipts[id]}}
function activity(s){state.activity.unshift(s);save()}
const workViews={
'Synthèse'(t){return `<div class="work-grid"><div class="stack"><section class="panel"><div class="panel-head"><h2>Le dossier, en une minute.</h2>${badge('Analyse démo','purple')}</div><div class="panel-body"><dl class="facts"><div><dt>Valeur indicative / durée totale</dt><dd>${cad(t.value)} avant taxes</dd></div><div><dt>Durée du contrat</dt><dd>${t.term}</dd></div><div><dt>Territoire</dt><dd>${t.region} · ${t.distance} km</dd></div><div><dt>Clôture</dt><dd>${t.close} · 10 h</dd></div></dl><ul class="brief-points"><li>${icon('snow',17)}<span>${t.trade==='Déneigement'?'Déneigement, déglaçage et maintien des voies d’accès. Intervention selon les seuils et les délais du devis.':t.trade==='Transport'?'Transport de neige depuis les sites de chargement jusqu’au dépôt municipal.':'Entretien saisonnier des espaces publics et des équipements associés.'}</span></li><li>${icon('truck',17)}<span>Équipement et disponibilité à démontrer. Vos actifs connus sont compatibles avec le scénario.</span></li><li>${icon('file',17)}<span>${t.pages} pages dans le dossier fictif. Les conditions essentielles sont reliées à leur extrait.</span></li></ul><div class="notice">${icon('alert',18)}<div><strong>À vérifier avant de poursuivre</strong><br>${t.visit}. La pertinence de  ${t.match}% ne constitue pas une admissibilité.<br><button class="source-link" data-action="source:visit">Consulter l’exigence · p. 12</button></div></div></div></section><section class="panel"><div class="panel-head"><h2>Pourquoi ce dossier ressort</h2>${icon('target',18)}</div><div class="panel-body"><div class="cost-row"><span>Dans votre rayon de ${state.radius} km</span>${badge(t.distance<=state.radius?'Compatible':'Hors rayon',t.distance<=state.radius?'':'amber')}</div><div class="cost-row"><span>Équipement déclaré</span>${badge('Capacité à confirmer','amber')}</div><div class="cost-row"><span>Projets comparables</span>${badge('3 références suggérées')}</div><div class="cost-row"><span>Conditions obligatoires</span>${badge('Revue humaine','purple')}</div></div></section></div><div class="stack" style="align-content:start">${paper('visit')}<section class="panel"><div class="panel-head"><h2>Votre décision</h2></div><div class="panel-body"><p class="note" style="margin-bottom:16px">Poursuivez le dossier ou conservez un motif de refus. Aucune soumission n’est transmise.</p><div style="display:flex;gap:9px">${btn('Ne pas poursuivre','decline:'+t.id)}${btn(state.pursuing.includes(t.id)?'Continuer':'Poursuivre','pursue:'+t.id,'primary','arrow')}</div></div></section></div></div>`},
'Exigences'(t){return `<div class="work-grid"><section class="panel"><div class="panel-head"><div><h2>Une exigence. Une preuve.</h2><p>Validez chaque élément après lecture de sa source.</p></div>${badge(requirements.filter(r=>checked(t.id,r[0])).length+'/8 revues','purple')}</div><div class="panel-body">${requirementsFor(t).map(r=>`<div class="requirement"><button class="check-btn ${checked(t.id,r[0])?'checked':''}" role="checkbox" aria-checked="${checked(t.id,r[0])}" aria-label="Revue : ${r[1]}" data-action="check:${r[0]}">${checked(t.id,r[0])?icon('check',13):''}</button><div><h3>${r[1]}</h3><p>${r[2]}</p><button class="source-link" data-action="source-inline:${r[0]}">${r[3]}</button></div></div>`).join('')}<div class="notice purple">${icon('shield',17)}<span>Ces cases enregistrent votre revue du scénario. Aucun registre ni organisme n’est vérifié par ce prototype.</span></div></div></section>${paper(sourceId)}</div>`},
'Chiffrage'(t){const p=priceValues(t),c=calcPrice(p);return `<div class="work-grid"><section class="panel"><div class="panel-head"><div><h2>Construisez votre prix.</h2><p>Coûts pour ${t.term.toLowerCase()} · CAD avant taxes</p></div><span class="pill purple" id="price-draft-state">${state.prices[t.id]?'Scénario enregistré':'Brouillon'}</span></div><div class="panel-body"><form id="price-form" class="form"><div class="form-row">${[['labor','Main-d’œuvre'],['equipment','Équipements'],['materials','Matériaux & abrasifs'],['overhead','Frais généraux'],['contingency','Provision pour imprévus']].map(([k,l])=>`<label>${l} (CAD)<input type="number" name="${k}" min="0" max="10000000" step="1" value="${p[k]}" required></label>`).join('')}<label>Marge brute cible (%)<input name="margin" type="number" min="0" max="60" step=".5" value="${p.margin}" required></label></div><div class="notice purple">${icon('chart',17)}<span>Prix = coût ÷ (1 − marge). La marge est calculée sur le prix de vente, et non comme une majoration du coût.</span></div><button type="submit" class="btn primary" style="justify-self:start">Enregistrer le scénario</button></form></div></section><div class="stack" style="align-content:start"><div class="price-total"><span style="font-size:11px">Prix indicatif avant taxes</span><strong id="price-result">${cad(c.price,2)}</strong><div class="cost-row"><span>Coût total</span><b id="cost-result">${cad(c.cost)}</b></div><div class="cost-row"><span>Marge brute prévue</span><b id="profit-result">${cad(c.profit,2)}</b></div><div class="cost-row"><span>Garantie illustrée · 5%</span><b id="bond-result">${cad(c.price*.05,2)}</b></div></div><section class="panel"><div class="panel-head"><h2>Point de comparaison</h2></div><div class="panel-body"><div class="cost-row"><span>Dernier contrat comparable</span><strong>${cad(t.value*.92)}</strong></div><div class="cost-row"><span>Durée comparable</span><strong>${t.term}</strong></div><p class="note" style="margin:20px 0">Montant historique fictif. Quantités, indexation et conditions peuvent différer.</p>${btn('Explorer les comparables','page:intelligence','link','arrow')}</div></section></div></div>`},
'Documents'(t){const f=state.forms[t.id]||{company:state.company,neq:'DEMO-NEQ-001',signatory:state.person,address:'120, rue des Ateliers, Saint-Bruno, QC'};return `<div class="work-grid"><section class="panel"><div class="panel-head"><div><h2>Moins de saisie. Plus de contrôle.</h2><p>Champs proposés à partir du profil fictif de l’entreprise.</p></div>${badge('Annexe A','purple')}</div><div class="panel-body"><form id="forms-form" class="form"><label>Raison sociale<input name="company" value="${esc(f.company)}" maxlength="80" required></label><div class="form-row"><label>NEQ de démonstration<input name="neq" value="${esc(f.neq)}" maxlength="30" required></label><label>Représentant autorisé<input name="signatory" value="${esc(f.signatory)}" required maxlength="60"></label></div><label>Adresse<input name="address" value="${esc(f.address)}" required maxlength="120"></label><div class="notice purple">${icon('file',17)}<span>Ces champs sont une proposition de formulaire. Aucune signature n’est insérée automatiquement.</span></div><button class="btn primary" type="submit" style="justify-self:start">Valider les champs proposés</button></form></div></section><section class="panel"><div class="panel-head"><h2>Pièces du dossier</h2>${badge('Version 2','gray')}</div><div class="panel-body">${[['Formulaire administratif','identity',state.forms[t.id]?'Champs revus':'À réviser'],['Bordereau de prix','price',state.prices[t.id]?'Prix enregistrés':'À compléter'],['Références comparables','references','3 preuves suggérées'],['Assurance responsabilité','insurance','À vérifier'],['Addenda 01','addendum',state.readAddenda.includes(t.id)?'Revu':'À lire']].map(x=>`<div class="requirement"><span class="file-icon">${icon('file',17)}</span><div><h3>${x[0]}</h3><p>${x[2]}</p></div><button class="icon-btn" style="margin-left:auto" data-action="${x[1]==='addendum'?'addendum:'+t.id:'source:'+x[1]}" aria-label="Voir ${x[0]}">${icon('arrow',15)}</button></div>`).join('')}<p class="note" style="margin-top:20px">Les previews sont des exemples. Le prototype n’édite pas les formulaires officiels des donneurs d’ordre.</p></div></section></div>`},
'Validation'(t){const complete=completion(t.id),ok=isApproved(t.id),receipt=state.receipts[t.id];let missing=requirementsFor(t).filter(r=>!checked(t.id,r[0]));return `<div class="work-grid"><section class="panel"><div class="panel-head"><h2>${receipt?'Dépôt enregistré dans la démo':ok?'Dossier revu. Prochaine étape : exporter.':'Un dernier regard avant l’export.'}</h2>${badge(receipt?'Déposée':ok?'Prête':'À réviser')}</div><div class="panel-body"><div style="display:flex;align-items:center;gap:22px;margin-bottom:24px"><div class="progress-ring" data-label="${complete}%" style="background:conic-gradient(#a48bbf 0deg ${complete*3.6}deg,#f0e8f6 ${complete*3.6}deg 360deg)"></div><div><h2>${8-missing.length} exigences revues sur 8</h2><p class="note" style="margin-top:9px">État de revue du scénario · Version 2</p></div></div>${missing.length?`<div class="notice">${icon('alert',18)}<span>${missing.length} exigences à revoir avant une approbation. ${missing.map(r=>r[1]).join(', ')}.</span></div>`:'<div class="notice green">'+icon('check',18)+'<span>La revue de toutes les exigences est enregistrée. Vérifiez aussi les prix et les champs administratifs.</span></div>'}<div class="cost-row"><span>Scénario de prix</span>${badge(state.prices[t.id]?'Enregistré':'Manquant')}</div><div class="cost-row"><span>Champs administratifs</span>${badge(state.forms[t.id]?'Revus':'À réviser')}</div><div class="cost-row"><span>Addenda version 2</span>${badge(state.readAddenda.includes(t.id)?'Revu':'À lire')}</div><div class="cost-row"><span>Signature officielle</span><strong>Hors démonstration</strong></div>${receipt?`<div class="notice green">${icon('check',18)}<span>Reçu démo : <strong>${esc(receipt.number)}</strong><br>Date déclarée : ${esc(receipt.date)}<br>Ce reçu local ne prouve aucun dépôt réel.</span></div>`:''}<div style="display:flex;gap:9px;flex-wrap:wrap;margin-top:24px">${btn('Revoir les exigences','tab:Exigences','','file')}${ok?btn('Exporter le manifeste démo','package-export:'+t.id,'primary','download'):btn('Revoir et approuver','review-approve:'+t.id,'primary','check')}</div></div></section><section class="panel"><div class="panel-head"><h2>Le chemin jusqu’au dépôt</h2></div><div class="panel-body">${[['1','Revoir et approuver','Une décision liée à une version précise.'],['2','Exporter le manifeste','L’export démo rassemble vos choix, sans formulaire officiel.'],['3','Signer et déposer','À effectuer par le signataire, dans le canal officiel.'],['4','Enregistrer le reçu','Le dépôt n’est constaté qu’avec un reçu renseigné.']].map((x,i)=>`<div class="requirement"><span class="avatar round">${x[0]}</span><div><h3>${x[1]}</h3><p>${x[2]}</p></div></div>`).join('')}${btn('Saisir un reçu de démonstration','receipt:'+t.id,'soft','file')}${(state.receiptHistory||[]).some(r=>r.tender===t.id)?btn('Historique des reçus','receipt-history:'+t.id,'link','clock'):''}<div class="notice purple">${icon('shield',17)}<span>Un addenda ou une modification des coûts invalide l’approbation et impose une nouvelle revue.</span></div></div></section></div>`}
};
let focusBefore;
function modal(title,sub,body,actions=''){const d=$('#dialog');focusBefore=document.activeElement;d.innerHTML=`<div class="dialog-head"><div><h2 id="dialog-title">${esc(title)}</h2>${sub?`<p>${esc(sub)}</p>`:''}</div><button class="icon-btn" aria-label="Fermer" data-action="close">${icon('close',19)}</button></div><div class="dialog-body">${body}</div>${actions?`<div class="dialog-actions">${actions}</div>`:''}`;if(!d.open)d.showModal()}
function close(){const d=$('#dialog');if(d.open)d.close();focusBefore?.isConnected&&focusBefore.focus()}
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog'))close()});
function download(name,text,type='text/plain'){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Fichier de démonstration téléchargé')}
function setCheck(key){state.checks[activeTender]||={};state.checks[activeTender][key]=!checked(activeTender,key);invalidate(activeTender);save();render()}
function historyFactor(){return filter==='Transport'?.42:filter==='Entretien'?.3:1}
function matchesCriteria(t){return t.distance<=state.radius&&(state.priceBand==='all'||state.priceBand==='under'&&t.value<500000||state.priceBand==='over'&&t.value>=500000)&&(state.tradeFilter==='Tout'||t.trade===state.tradeFilter)}
function radarCount(){return tenders.filter(t=>!state.pursuing.includes(t.id)&&!state.declined[t.id]&&matchesCriteria(t)).length}
function requirementsFor(t){return requirements.map(r=>r[0]==='visit'?[r[0],'Visite des lieux',t.visit+' · Revoir la condition propre à ce dossier.',r[3]]:r)}
function sourceFor(key){const t=tender();if(key==='visit')return ['3.4 — Visite des lieux','12',t.visit.startsWith('Aucune')?'Aucune visite obligatoire n’est prévue pour ce dossier fictif. Le soumissionnaire reste responsable de la lecture des conditions particulières.':t.visit.startsWith('Visite effectuée')?t.visit+'. Une preuve de présence est consignée dans le scénario et reste à vérifier par le signataire.':'Une visite obligatoire est prévue : '+t.visit+'. Le soumissionnaire doit faire constater sa présence par le représentant désigné.'];return sourceCopy[key]||sourceCopy.visit}
function blockers(id){let t=tenders.find(x=>x.id===id);if(!t)return ['Dossier inconnu'];let missing=requirementsFor(t).filter(r=>!checked(id,r[0])).map(r=>r[1]);if(!validPrice(state.prices[id]))missing.push('Scénario de prix enregistré et valide');if(!state.forms[id]||!['company','neq','signatory','address'].every(k=>String(state.forms[id][k]||'').trim()))missing.push('Champs administratifs validés');if(!state.readAddenda.includes(id))missing.push('Addenda 01 revu');return missing}
function packageFingerprint(id){return JSON.stringify({version:2,checks:requirements.map(r=>[r[0],checked(id,r[0])]),price:state.prices[id]||null,forms:state.forms[id]||null,addendum:state.readAddenda.includes(id)})}
function isApproved(id){return state.approved.includes(id)&&state.approvalSnapshots[id]?.fingerprint===packageFingerprint(id)&&blockers(id).length===0}
function isExported(id){return isApproved(id)&&state.exported.includes(id)&&state.exportSnapshots[id]===packageFingerprint(id)}
function approval(id){let t=tenders.find(x=>x.id===id);activeTender=id;let missing=blockers(id);if(missing.length){modal('Le dossier demande encore une revue.',`${t.short} · Version 2`,`<div class="notice">${icon('alert',18)}<span>L’approbation reste en attente jusqu’à la résolution des éléments suivants.</span></div><ul class="brief-points">${missing.map(m=>`<li>${icon('file',15)}${esc(m)}</li>`).join('')}</ul>`,btn('Reprendre la revue','tab:Exigences','primary'));return}modal('Approuver cette version du scénario.',`${t.short} · Version 2`,`<div class="price-total"><span>Prix avant taxes à approuver</span><strong>${cad(calcPrice(state.prices[id]).price,2)}</strong></div><form class="form" id="approve-form" data-id="${id}" data-snapshot="${esc(packageFingerprint(id))}" style="margin-top:23px"><label style="display:flex;gap:10px;align-items:start"><input type="checkbox" name="confirm" required>J’ai revu les exigences, les pièces et le prix de ce dossier fictif.</label><div class="notice purple">${icon('shield',18)}<span>Cette décision enregistre une approbation locale. Elle ne signe aucun document et n’autorise aucun dépôt réel.</span></div><button type="submit" class="btn primary">Approuver le dossier de démonstration</button></form>`)}
function sourceModal(key){const s=sourceFor(key);modal(s[0],`Source fictive · Page ${s[1]} · ${activeTender}`,paper(key),btn('Retour au dossier','close','primary'))}
function addendum(id){activeTender=id;modal('Un changement à revoir.','Addenda 01 · Version 2 · Document fictif',`<div class="notice">${icon('alert',18)}<span>Un changement de quantité modifie le chiffrage. La première revue de ce changement demande une nouvelle validation du prix. Relire un addenda déjà revu conserve votre travail.</span></div><div class="table-wrap"><table><thead><tr><th>Élément</th><th>Version 1</th><th>Version 2</th></tr></thead><tbody><tr><td>Réseau à desservir</td><td>42,0 km</td><td><strong>46,5 km</strong></td></tr><tr><td>Bordereau applicable</td><td>Version 1</td><td><strong>Version 2</strong></td></tr><tr><td>Date de clôture</td><td>Inchangée</td><td>Inchangée</td></tr></tbody></table></div><p class="note" style="margin-top:20px">La lecture de l’addenda n’approuve pas automatiquement les nouveaux prix.</p>`,btn('Lire la source','source:addendum')+btn('Marquer l’addenda comme revu','ack-addendum:'+id,'primary','check'))}
function criteria(){modal('Ce qui fait un bon match','Critères du radar de démonstration',`<form class="form" id="criteria-form"><label>Rayon maximal (km)<input name="radius" type="number" min="10" max="500" value="${state.radius}" required></label><label>Valeur de contrat<select name="priceBand">${[['all','Tous les montants du scénario'],['under','Moins de 500 000 $'],['over','500 000 $ et plus']].map(([v,l])=>`<option value="${v}" ${state.priceBand===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Métier<select name="tradeFilter">${['Tout','Déneigement','Transport','Entretien'].map(t=>`<option ${state.tradeFilter===t?'selected':''}>${t}</option>`).join('')}</select></label><div class="notice purple">${icon('target',18)}<span>Ces critères filtrent réellement les avis fictifs. Les dossiers déjà poursuivis restent dans votre suivi. L’admissibilité demande une revue distincte.</span></div><button class="btn primary" type="submit">Appliquer au radar</button></form>`)}
async function action(a){const [kind,id]=a.split(':');switch(kind){
case 'close':close();break;
case 'menu':$('.sidebar').classList.toggle('open');break;
case 'page':close();go(id);break;
case 'tender':close();openTender(id);break;
case 'tab':close();workTab=id;go('workbench');break;
case 'save':state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];save();render();toast(state.saved.includes(id)?'Dossier enregistré':'Dossier retiré des favoris');break;
case 'pursue':delete state.declined[id];if(!state.pursuing.includes(id))state.pursuing.push(id);activity('Dossier ajouté au suivi · '+tenders.find(t=>t.id===id).short);close();openTender(id,'Exigences');toast('Dossier ajouté à vos soumissions');break;
case 'decline':if(state.receipts[id]){modal('Un reçu est déjà consigné.','L’historique du dépôt doit rester traçable.','<p class="note">La démo conserve le reçu existant. Elle ne simule pas de retrait sur un portail officiel.</p>');break}modal('Conserver votre décision','Votre décision reste accessible dans l’onglet Écartés du radar.',`<form class="form" id="decline-form" data-id="${id}"><label>Motif<select name="reason"><option>Capacité insuffisante</option><option>Conditions peu favorables</option><option>Territoire trop éloigné</option><option>Calendrier incompatible</option></select></label><label>Note facultative<textarea name="note"></textarea></label><button class="btn primary" type="submit">Enregistrer la décision</button></form>`);break;
case 'check':setCheck(id);break;
case 'source':sourceModal(id);break;
case 'source-inline':sourceId=id;render();break;
case 'addendum':addendum(id);break;
case 'ack-addendum':if(state.readAddenda.includes(id)){close();toast('Cet addenda est déjà revu. Vos prix sont conservés.');break}state.readAddenda.push(id);state.checks[id]||={};state.checks[id].addendum=true;state.checks[id].price=false;invalidate(id);activity('Addenda 01 revu · '+tenders.find(t=>t.id===id).short+' · Prix à revalider');close();openTender(id,'Chiffrage');toast('Addenda revu · Prix conservés, à revalider');break;
case 'review-approve':approval(id);break;
case 'package-export':if(!isApproved(id)){invalidate(id);save();approval(id);break}{let t=tenders.find(t=>t.id===id);download(id+'-manifeste-DEMO.html',`<!doctype html><html lang="fr"><meta charset="utf-8"><title>Manifeste de démonstration</title><style>body{font:15px system-ui;max-width:800px;margin:70px auto;line-height:1.8;color:#42354d}h1{font-size:30px}table{width:100%;border-collapse:collapse}td{padding:10px;border-bottom:1px solid #ddd}.label{color:#8e6fa6}</style><p class="label">TENDERSTRIKE · DONNÉES FICTIVES · NON VALABLE POUR UN DÉPÔT</p><h1>${esc(t.title)}</h1><p>${id} · Version 2 · ${esc(state.forms[id].company)}</p><h2>Scénario approuvé</h2><p>Prix : ${cad(calcPrice(state.prices[id]).price,2)} CAD avant taxes</p><table>${requirements.map(r=>`<tr><td>${r[1]}</td><td>Revue locale enregistrée</td></tr>`).join('')}</table><h2>Formulaire proposé</h2>${Object.entries(state.forms[id]).map(([k,v])=>`<p>${esc(k)} : ${esc(v)}</p>`).join('')}<p>Ce manifeste ne contient ni formulaires officiels, ni signature, ni preuve de dépôt. Aucune information n’a été transmise à un donneur d’ordre.</p></html>`,'text/html');if(!state.exported.includes(id))state.exported.push(id);state.exportSnapshots[id]=packageFingerprint(id);activity('Manifeste démo exporté · '+t.short);render();break}
case 'receipt':if(!isExported(id)){modal('Exportez d’abord la version approuvée.','Le parcours de dépôt conserve l’ordre des étapes.',`<div class="notice purple">${icon('file',17)}<span>La saisie d’un reçu s’ouvre après la revue et l’export du manifeste de démonstration.</span></div>`,btn('Revoir la validation','tab:Validation','primary'));break}modal('Enregistrer un reçu de démonstration','Aucune connexion au portail officiel.',`<form id="receipt-form" class="form" data-id="${id}"><label>Référence du reçu fictif<input name="number" placeholder="DEMO-RECU-2026-001" required minlength="5" maxlength="60"></label><label>Date / heure déclarées<input type="datetime-local" name="date" value="2026-10-23T14:30" required></label><label style="display:flex;align-items:start;gap:9px"><input type="checkbox" name="demoAcknowledged" required>Je comprends que cette saisie ne constitue pas un dépôt réel.</label><button class="btn primary" type="submit">Enregistrer le reçu fictif</button></form>`);break;
case 'receipt-history':modal('Les reçus précédents restent conservés.','Historique local · Aucun dépôt officiel',`<div class="stack">${(state.receiptHistory||[]).filter(r=>r.tender===id).map(r=>`<div class="notice purple"><span><strong>${esc(r.number)}</strong><br>${esc(r.date)} · Version précédente du scénario</span></div>`).join('')}</div>`);break;
case 'historical':{const rows=[['Saint-Bruno','2023',1140000,'4 prix connus'],['Boucherville','2024',398000,'2 prix connus'],['Sainte-Julie','2023',862000,'3 prix connus']],r=rows[Number(id)];modal('Comparable · '+r[0],'Échantillon fictif · Prix avant taxes',`<dl class="facts"><div><dt>Cycle</dt><dd>${r[1]}</dd></div><div><dt>Montant retenu</dt><dd>${cad(r[2]*historyFactor())}</dd></div><div><dt>Couverture de l’exemple</dt><dd>${r[3]}</dd></div><div><dt>Nature</dt><dd>Prix d’ouverture</dd></div></dl><div class="notice purple">${icon('file',17)}<span>Comparabilité à revoir : quantité, durée, indexation, options et taxes. Ces données sont inventées pour démontrer le produit.</span></div>`,btn('Ouvrir un scénario de prix','open-price','primary'));break}
case 'open-price':close();openTender(activeTender,'Chiffrage');break;
case 'vault-doc':modal('Preuve du coffre-fort','Document fictif · Réutilisation après validation',id==='amp'?`<div class="notice purple">${icon('shield',18)}<span>Ce dossier demande une vérification du statut au registre et des obligations applicables. L’interface n’invente pas une expiration pour toutes les autorisations.</span></div><div class="cost-row"><span>Statut réel du registre</span><strong>Non vérifié</strong></div><div class="cost-row"><span>Source disponible</span><strong>Simulation uniquement</strong></div>`:id==='equipment'?`<dl class="facts"><div><dt>Chasse-neige</dt><dd>8 véhicules</dd></div><div><dt>Chargeurs</dt><dd>4 équipements</dd></div><div><dt>Disponibilité</dt><dd>À confirmer par saison</dd></div><div><dt>État des preuves</dt><dd>Échantillon fictif</dd></div></dl>`:id.startsWith('local-')?`<h3>${esc(state.documents[Number(id.slice(6))]?.name)}</h3><p class="note" style="white-space:pre-wrap;margin-top:15px">${esc(state.documents[Number(id.slice(6))]?.note||'Aucune note ajoutée.')}</p><div class="notice purple">Métadonnées locales · Aucun fichier analysé · À vérifier</div>`:paper(sourceCopy[id]?id:'identity'),btn('Fermer','close','primary'));break;
case 'company-profile':modal('Profil de l’entreprise','Source proposée pour les champs administratifs',`<dl class="facts"><div><dt>Raison sociale</dt><dd>${esc(state.company)}</dd></div><div><dt>NEQ fictif</dt><dd>DEMO-NEQ-001</dd></div><div><dt>Signataire proposé</dt><dd>${esc(state.person)}</dd></div><div><dt>Territoire</dt><dd>Montérégie · ${state.radius} km</dd></div></dl><div class="notice purple">${icon('building',17)}<span>Profil de démonstration. Aucun registre externe n’a été interrogé.</span></div>`,btn('Modifier les préférences','page:settings','primary'));break;
case 'add-document':modal('Ajouter une fiche documentaire','Métadonnées locales · Aucun téléversement externe',`<form class="form" id="document-form"><label>Titre<input name="name" required maxlength="90" placeholder="Attestation ou référence de projet"></label><label>Catégorie<select name="type"><option>Conformité</option><option>Assurances</option><option>Références</option><option>Équipements</option><option>Entreprise</option></select></label><label>Note<textarea name="note" maxlength="500"></textarea></label><div class="notice purple">${icon('file',17)}<span>La fiche sera marquée « À vérifier ». Ce prototype ne lit aucun fichier réel.</span></div><button type="submit" class="btn primary">Ajouter la fiche</button></form>`);break;
case 'calendar-week':calendarNext=!calendarNext;render();break;
case 'event':activeTender='TS-2026-087';modal('Visite obligatoire · Saint-Bruno','Mercredi 28 octobre 2026 · 10 h',`<dl class="facts"><div><dt>Dossier</dt><dd>TS-2026-087</dd></div><div><dt>Responsable suggérée</dt><dd>Marie Lavoie</dd></div><div><dt>Point de rencontre</dt><dd>À confirmer dans le devis</dd></div><div><dt>Preuve attendue</dt><dd>Confirmation de présence</dd></div></dl><div class="notice">${icon('alert',17)}<span>L’ajout au calendrier ne constitue pas une preuve de présence.</span></div>`,btn('Lire l’exigence','source:visit')+btn('Créer la tâche de visite','visit-task','primary'));break;
case 'visit-task':if(state.tasks.some(t=>t.id==='visit-087')){close();toast('La tâche de visite existe déjà.');break}state.tasks.push({id:'visit-087',title:'Confirmer le lieu et assister à la visite — Saint-Bruno',owner:'Marie Lavoie',date:'2026-10-28',done:false});save();close();toast('Tâche de visite ajoutée à l’équipe');break;
case 'task':modal('Créer une tâche','Une responsabilité explicite, liée à votre équipe.',`<form class="form" id="task-form"><label>Action à réaliser<input name="title" required maxlength="100"></label><div class="form-row"><label>Responsable<select name="owner"><option>Alexandre Roy</option><option>Marie Lavoie</option><option>Claire Dubois</option></select></label><label>Échéance<input name="date" type="date" value="2026-10-26" required></label></div><button type="submit" class="btn primary">Créer la tâche locale</button></form>`);break;
case 'task-toggle':state.tasks[Number(id)].done=!state.tasks[Number(id)].done;save();render();toast(state.tasks[Number(id)].done?'Tâche terminée':'Tâche réouverte');break;
case 'new-member':modal('Ajouter un membre fictif','Aucune invitation n’est envoyée.',`<form class="form" id="member-form"><label>Nom<input name="name" required maxlength="60"></label><label>Rôle<select name="role"><option>Estimatrice / estimateur</option><option>Administration</option><option>Lecture seule</option></select></label><div class="notice purple">${icon('shield',17)}<span>La démo présente les rôles. Elle ne crée aucun compte ni droit d’accès réel.</span></div><button type="submit" class="btn primary">Ajouter au scénario</button></form>`);break;
case 'toggle':state[id]=!state[id];save();render();toast('Préférence locale mise à jour');break;
case 'criteria':criteria();break;
case 'tour':modal('Du radar au dossier revu.','Un parcours complet, avec des données fictives.',`<div class="stack">${[['radar','1. Trouver un dossier','Le territoire et l’équipement expliquent la pertinence.'],['file','2. Revoir les exigences','Les points importants renvoient à un extrait lisible.'],['chart','3. Construire le prix','Vos coûts et votre marge déterminent un scénario.'],['shield','4. Préparer et approuver','Les pièces, les champs et la version restent traçables.']].map(x=>`<div class="activity"><span class="activity-icon">${icon(x[0],17)}</span><div><h3>${x[1]}</h3><p style="margin-top:6px">${x[2]}</p></div></div>`).join('')}</div>`,btn('Explorer Saint-Bruno','tender:TS-2026-087','primary','arrow'));break;
case 'notifications':modal('Ce qui mérite votre attention','Instantané fictif · 23 octobre 2026',`<div class="activity"><span class="activity-icon">${icon('file',17)}</span><div><h3>Addenda · Sainte-Julie</h3><p>La quantité change. Le prix doit être revu.</p>${btn('Ouvrir l’impact','addendum:TS-2026-081','link','arrow')}</div></div><div class="activity"><span class="activity-icon">${icon('calendar',17)}</span><div><h3>Visite · Saint-Bruno</h3><p>Le 28 octobre à 10 h. Confirmez le lieu.</p>${btn('Voir la visite','event:visit','link','arrow')}</div></div>${state.digest?'<div class="activity"><span class="activity-icon">'+icon('radar',17)+'</span><div><h3>Brief du matin prêt</h3><p>'+radarCount()+' opportunités correspondent aux critères du radar.</p></div></div>':''}`);break;
case 'assistant':modal('Un assistant, des sources visibles.','Réponses scénarisées · Aucune IA connectée',`<div class="notice purple">${icon('spark',18)}<span>Choisissez un point du dossier fictif. L’assistant vous mène aux données et à l’action à revoir.</span></div><div class="stack">${btn('Quel dossier mérite une revue aujourd’hui?','assist:radar','','radar')}${btn('Qu’est-ce qui bloque mon export?','assist:validation','','shield')}${btn('Que change le nouvel addenda?','assist:addendum','','file')}</div>`);break;
case 'assist':if(id==='radar')modal('Saint-Bruno ressort dans votre territoire.','Réponse scénarisée · Sources fictives',`<p class="note" style="font-size:13px">Le dossier est à 24 km, porte sur trois saisons et correspond à votre parc d’équipements déclaré. La visite du 28 octobre et les pièces obligatoires restent à vérifier.</p><div class="notice purple">${icon('file',17)}<span>Sources : fiche TS-2026-087 et devis fictif, page 12.</span></div>`,btn('Examiner le dossier','tender:TS-2026-087','primary'));else if(id==='validation'){close();openTender(activeTender,'Validation')}else addendum('TS-2026-081');break;
case 'global-search':modal('Retrouver un dossier','Rechercher dans les avis fictifs de la démonstration.',`<label class="search" style="margin:0;width:100%">${icon('search',17)}<input id="global-search" placeholder="Ville, métier, référence…" aria-label="Rechercher tous les dossiers" style="width:100%;height:45px" autofocus></label><div id="search-results" style="margin-top:15px">${tenders.slice(0,4).map(t=>`<button class="requirement" style="width:100%;text-align:left" data-action="tender:${t.id}">${icon('building',17)}<span><h3>${t.short}</h3><p>${t.title}</p></span></button>`).join('')}</div>`);break;
case 'export-tracker':download('tenderstrike-suivi-DEMO.csv','DEMO;Reference;Ville;Valeur CAD;Etape;Cloture\n'+tenders.filter(t=>state.pursuing.includes(t.id)).map(t=>['true',t.id,t.short,t.value,stage(t),t.close].join(';')).join('\n'),'text/csv');break;
case 'export-prices':download('tenderstrike-comparables-DEMO.csv','DEMO;Metier;Entreprise;Prix ouverture CAD;Periode\n'+[['Nord-Est Services',1140000],['Groupe des Rives',1185000],['Excavation Mont-Val',1290000],['Services Hivernis',1325000]].map(([name,price])=>['true',filter==='Transport'?'Transport':filter==='Entretien'?'Entretien':'Déneigement',name,Math.round(price*historyFactor()),'2023-2025'].join(';')).join('\n'),'text/csv');break;
case 'reset':modal('Repartir du scénario initial?','Seules les données locales de TenderStrike sont concernées.','<p class="note">Les favoris, décisions, scénarios et reçus fictifs seront restaurés à leur état initial. Aucun autre projet ne sera modifié.</p>',btn('Conserver','close')+btn('Réinitialiser','reset-confirm','primary'));break;
case 'reset-confirm':state=structuredClone(initial);save();close();go('radar');toast('Démonstration réinitialisée');break;
}}
document.addEventListener('click',e=>{let b=e.target.closest('[data-action],[data-page],[data-filter]');if(!b)return;if(b.dataset.page)go(b.dataset.page);else if(b.dataset.filter){filter=b.dataset.filter;render()}else action(b.dataset.action)});
document.addEventListener('input',e=>{if(e.target.id==='search'){let pos=e.target.selectionStart;query=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)}if(e.target.closest('#price-form')){let p=Object.fromEntries(new FormData($('#price-form'))),c=calcPrice(p);$('#price-result').textContent=c.valid?cad(c.price,2):'À vérifier';$('#cost-result').textContent=c.valid?cad(c.cost):'—';$('#profit-result').textContent=c.valid?cad(c.profit,2):'—';$('#bond-result').textContent=c.valid?cad(c.price*.05,2):'—';$('#price-draft-state').textContent='Modifications non enregistrées'}if(e.target.id==='global-search'){let q=e.target.value.toLowerCase(),ls=tenders.filter(t=>JSON.stringify(t).toLowerCase().includes(q));$('#search-results').innerHTML=ls.map(t=>`<button class="requirement" style="width:100%;text-align:left" data-action="tender:${t.id}">${icon('building',17)}<span><h3>${t.short}</h3><p>${t.title}</p></span></button>`).join('')||'<div class="empty">Aucun dossier correspondant.</div>'}});
function handleSubmit(f){if(f.checkValidity&&!f.checkValidity()){f.reportValidity?.();return}const d=Object.fromEntries(new FormData(f));switch(f.id){
case 'price-form':if(!validPrice(d)){toast('Vérifiez les coûts : total positif, catégories de 0 à 10 M$ et marge de 0 à 60 %.');return}invalidate(activeTender);state.prices[activeTender]=Object.fromEntries(Object.entries(d).map(([k,v])=>[k,+v]));state.checks[activeTender]||={};state.checks[activeTender].price=true;activity('Scénario de prix enregistré · '+tender().short);render();toast('Scénario enregistré · Prix à nouveau revu');return true;
case 'forms-form':if(!['company','neq','signatory','address'].every(k=>String(d[k]||'').trim())){toast('Complétez les quatre champs administratifs.');return}invalidate(activeTender);state.forms[activeTender]=d;state.checks[activeTender]||={};state.checks[activeTender].identity=true;activity('Champs administratifs revus · '+tender().short);render();toast('Champs proposés validés localement');return true;
case 'approve-form':{const id=f.dataset.id;if(!d.confirm){toast('Confirmez la revue avant d’approuver.');return}if(blockers(id).length||f.dataset.snapshot!==packageFingerprint(id)){approval(id);toast('Le dossier a changé. Relisez la version actuelle.');return}if(!state.approved.includes(id))state.approved.push(id);state.approvalSnapshots[id]={fingerprint:packageFingerprint(id),approvedBy:state.person,approvedAt:new Date().toISOString(),version:2};if(!state.pursuing.includes(id))state.pursuing.push(id);delete state.declined[id];activity('Dossier version 2 approuvé (démo) · '+tenders.find(t=>t.id===id).short);close();render();toast('Version 2 approuvée dans la démo');break;}
case 'receipt-form':{const id=f.dataset.id;if(!isExported(id)||!d.demoAcknowledged){toast('Exportez la version approuvée et confirmez le caractère fictif du reçu.');return}if(!String(d.number||'').trim()||!d.date){toast('La référence et la date du reçu sont requises.');return}if(state.receipts[id]){state.receiptHistory||=[];state.receiptHistory.push({tender:id,...state.receipts[id]})}state.receipts[id]={...d,packageFingerprint:packageFingerprint(id),recordedAt:new Date().toISOString()};activity('Reçu fictif enregistré · '+d.number);close();render();toast('Dépôt de démonstration enregistré');break;}
case 'decline-form':{const id=f.dataset.id;if(state.receipts[id])return;state.pursuing=state.pursuing.filter(x=>x!==id);invalidate(id);state.declined[id]={reason:d.reason,note:d.note,decidedBy:state.person,decidedAt:new Date().toISOString()};activity('Dossier non poursuivi · '+id+' · '+d.reason+(d.note?' · '+d.note:''));close();go('radar');toast('Décision conservée dans Écartés et dans le journal');break;}
case 'settings-form':if(!String(d.company||'').trim()||!String(d.person||'').trim()||!Number.isFinite(+d.radius)||+d.radius<10||+d.radius>500){toast('Vérifiez le profil et le rayon de 10 à 500 km.');return}state.company=d.company.trim();state.person=d.person.trim();state.radius=+d.radius;save();render();toast('Préférences enregistrées · Les dossiers approuvés gardent leurs champs originaux.');break;
case 'criteria-form':if(!Number.isFinite(+d.radius)||+d.radius<10||+d.radius>500)return;state.radius=+d.radius;state.priceBand=['all','under','over'].includes(d.priceBand)?d.priceBand:'all';state.tradeFilter=['Tout','Déneigement','Transport','Entretien'].includes(d.tradeFilter)?d.tradeFilter:'Tout';save();close();filter='Tout';render();toast(radarCount()+' dossier(s) selon vos critères.');break;
case 'document-form':if(!String(d.name||'').trim())return;state.documents.push(d);activity('Fiche documentaire ajoutée · '+d.name);close();render();toast('Fiche ajoutée · À vérifier');break;
case 'task-form':if(!String(d.title||'').trim()||!d.date)return;state.tasks.push({...d,done:false});activity('Tâche attribuée à '+d.owner+' · '+d.title);close();render();toast('Tâche locale créée');break;
case 'member-form':if(!String(d.name||'').trim())return;state.team.push(d);activity('Membre ajouté au scénario · '+d.name);close();render();toast('Membre fictif ajouté · Aucune invitation envoyée');break;
}}
document.addEventListener('submit',e=>{e.preventDefault();handleSubmit(e.target)});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();action('global-search')}if(e.key==='Escape')$('.sidebar')?.classList.remove('open')});
function hashRoute(){let route;try{route=decodeURIComponent(location.hash.slice(1))}catch{route='radar'}let bits=route.split('/');const oldPage=page;if(bits[0]==='workbench'&&tenders.some(t=>t.id===bits[1])){activeTender=bits[1];workTab=workViews[bits[2]]?bits[2]:'Synthèse';page='workbench'}else page=nav.some(n=>n[0]===bits[0])?bits[0]:'radar';if(oldPage!==page){filter=page==='intelligence'?'Déneigement':'Tout';query=''}render()}
window.addEventListener('hashchange',hashRoute);hashRoute();
